import React, { Suspense } from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

// ONLY load landing page components immediately - NOTHING ELSE
// This makes the homepage load instantly with minimal bundle size
import LandingPage from '../components/landing/LandingPage';
import ArtistsLandingPage from '../components/landing/ArtistsLandingPage';
import PropertyLogin from '../components/landing/PropertyLogin';
import ArtistLogin from '../components/landing/ArtistLogin';
import ArtistApplication from '../components/public/ArtistApplication';

// Lazy load EVERYTHING else including the entire dashboard
// Dashboard and all its routes only load when user logs in
const ProtectedRoute = React.lazy(() => import('./ProtectedRoute'));
const DashboardLayout = React.lazy(() => import('../components/layout/DashboardLayout'));

// Artist Components (only loaded when needed)
const ArtistDashboard = React.lazy(() => import('../components/artist/ArtistDashboard'));
const ArtistProfile = React.lazy(() => import('../components/artist/ArtistProfile'));
const ArtistPortfolio = React.lazy(() => import('../components/artist/ArtistPortfolio'));
const ArtistProjects = React.lazy(() => import('../components/artist/ArtistProjects'));
const ArtistPastProjects = React.lazy(() => import('../components/artist/ArtistPastProjects'));
const ArtistApplications = React.lazy(() => import('../components/artist/ArtistApplications'));
const ArtistPricingSettings = React.lazy(() => import('../components/artist/ArtistPricingSettings'));
const BrowseProjects = React.lazy(() => import('../components/artist/BrowseProjects'));
const ProfileCompletionPrompt = React.lazy(() => import('../components/artist/ProfileCompletionPrompt'));
const ArtistApplicationForm = React.lazy(() => import('../components/artist/ArtistApplicationForm'));

// Architect Components (only loaded when needed)
const ArchitectDashboard = React.lazy(() => import('../components/architect/ArchitectDashboard'));
const BrowseArtists = React.lazy(() => import('../components/architect/BrowseArtists'));
const PostProject = React.lazy(() => import('../components/architect/PostProject'));
const ArchitectProjects = React.lazy(() => import('../components/architect/ArchitectProjects'));
const ArchitectPastProjects = React.lazy(() => import('../components/architect/ArchitectPastProjects'));
const Applications = React.lazy(() => import('../components/architect/Applications'));

// Shared Components (only loaded when needed)
const Messages = React.lazy(() => import('../components/messages/Messages'));
const Notifications = React.lazy(() => import('../components/notifications/Notifications'));
const LoyaltyProgram = React.lazy(() => import('../components/loyalty/LoyaltyProgram'));
const ProfileSettings = React.lazy(() => import('../components/shared/ProfileSettings'));
const ProjectDetail = React.lazy(() => import('../components/projects/ProjectDetail'));
const ProjectOverview = React.lazy(() => import('../components/projects/ProjectOverview'));

// Admin Components (only loaded when needed)
const AdminDashboard = React.lazy(() => import('../components/admin/AdminDashboard'));
const ArtistApplicationReview = React.lazy(() => import('../components/admin/ArtistApplicationReview'));
const ArtistProfileReview = React.lazy(() => import('../components/admin/ArtistProfileReview'));
const BlogManagement = React.lazy(() => import('../components/admin/BlogManagement'));
const BlogEditor = React.lazy(() => import('../components/admin/BlogEditor'));

// Blog Components (public - lazy loaded)
const BlogListing = React.lazy(() => import('../components/blog/BlogListing'));
const BlogPost = React.lazy(() => import('../components/blog/BlogPost'));

// Legal Pages (public - lazy loaded)
const TermsAndConditions = React.lazy(() => import('../components/legal/TermsAndConditions'));
const PrivacyPolicy = React.lazy(() => import('../components/legal/PrivacyPolicy'));

// Contact Page (public - lazy loaded)
const Contact = React.lazy(() => import('../components/contact/Contact'));

// Loading component shown while lazy components load
const LoadingFallback = () => (
  <div style={{
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    minHeight: '400px',
    fontSize: '16px',
    color: '#666'
  }}>
    Loading...
  </div>
);

const AppRoutes = () => {
  const { user, profile, loading } = useAuth();
  const [forceShowApp, setForceShowApp] = React.useState(false);

  console.log('AppRoutes - user:', user?.id, 'profile:', profile, 'loading:', loading);

  // EMERGENCY: Force show app after 10 seconds if still loading
  React.useEffect(() => {
    const emergencyTimer = setTimeout(() => {
      if (loading) {
        console.error('🚨 EMERGENCY: Loading timeout - forcing app to show');
        setForceShowApp(true);
      }
    }, 10000);

    return () => clearTimeout(emergencyTimer);
  }, [loading]);

  // Don't show loading screen for public routes (landing page)
  // Only show loading for dashboard routes where auth is required
  // This makes the homepage appear instantly
  if (loading && !forceShowApp && window.location.pathname.startsWith('/dashboard')) {
    return (
      <div className="loading-screen">
        <div className="logo-icon">3D</div>
        <p>Loading...</p>
      </div>
    );
  }

  return (
    <Routes>
      {/* Public Routes */}
      <Route path="/" element={user && profile ? <Navigate to="/dashboard" /> : <LandingPage />} />
      <Route path="/for-artists" element={<ArtistsLandingPage />} />
      <Route path="/login" element={user && profile ? <Navigate to="/dashboard" /> : <Navigate to="/login/property" />} />
      <Route path="/login/property" element={user && profile ? <Navigate to="/dashboard" /> : <PropertyLogin />} />
      <Route path="/login/artist" element={user && profile ? <Navigate to="/dashboard" /> : <ArtistLogin />} />
      <Route path="/apply-artist" element={<ArtistApplication />} />

      {/* Protected Dashboard Routes - Single Suspense wrapper */}
      <Route
        path="/dashboard/*"
        element={
          <Suspense fallback={<LoadingFallback />}>
            <ProtectedRoute>
              <DashboardLayout />
            </ProtectedRoute>
          </Suspense>
        }
      >
        {/* Home/Welcome Dashboard */}
        <Route index element={
          profile?.user_type === 'artista' ? (
            profile?.approval_status === 'approved' ? (
              <ArtistDashboard />
            ) : (
              <ProfileCompletionPrompt profile={profile} />
            )
          ) : profile?.user_type === 'arquiteto' ? (
            <ArchitectDashboard />
          ) : (
            <div className="content-section">
              <h1>Welcome, {profile?.full_name || 'User'}! 👋</h1>
              <p>Select an option from the sidebar to get started.</p>
            </div>
          )
        } />

        {/* Shared Routes - No nested Suspense needed */}
        <Route path="messages" element={<Messages />} />
        <Route path="notifications" element={<Notifications />} />
        <Route path="settings" element={
          <ProtectedRoute>
            <ProfileSettings />
          </ProtectedRoute>
        } />

        {/* Artist Routes - No nested Suspense, parent handles it */}
        <Route path="artist/apply" element={
          <ProtectedRoute requiredUserType="artista" requiresApproval={false}>
            <ArtistApplicationForm />
          </ProtectedRoute>
        } />
        <Route path="artist/browse-projects" element={
          <ProtectedRoute requiredUserType="artista">
            <BrowseProjects />
          </ProtectedRoute>
        } />
        <Route path="artist/profile" element={
          <ProtectedRoute requiredUserType="artista" requiresApproval={false}>
            <ArtistProfile />
          </ProtectedRoute>
        } />
        <Route path="artist/portfolio" element={
          <ProtectedRoute requiredUserType="artista" requiresApproval={false}>
            <ArtistPortfolio />
          </ProtectedRoute>
        } />
        <Route path="artist/pricing" element={
          <ProtectedRoute requiredUserType="artista">
            <ArtistPricingSettings />
          </ProtectedRoute>
        } />
        <Route path="artist/applications" element={
          <ProtectedRoute requiredUserType="artista">
            <ArtistApplications />
          </ProtectedRoute>
        } />
        <Route path="artist/projects" element={
          <ProtectedRoute requiredUserType="artista">
            <ArtistProjects />
          </ProtectedRoute>
        } />
        <Route path="artist/past-projects" element={
          <ProtectedRoute requiredUserType="artista">
            <ArtistPastProjects />
          </ProtectedRoute>
        } />
        <Route path="artist/project/:id" element={
          <ProtectedRoute requiredUserType="artista">
            <ProjectOverview />
          </ProtectedRoute>
        } />
        <Route path="artist/project/:id/detail" element={
          <ProtectedRoute requiredUserType="artista">
            <ProjectDetail />
          </ProtectedRoute>
        } />

        {/* Architect Routes - No nested Suspense, parent handles it */}
        <Route path="architect/browse-artists" element={
          <ProtectedRoute requiredUserType="arquiteto">
            <BrowseArtists />
          </ProtectedRoute>
        } />
        <Route path="architect/post-project" element={
          <ProtectedRoute requiredUserType="arquiteto">
            <PostProject />
          </ProtectedRoute>
        } />
        <Route path="architect/projects" element={
          <ProtectedRoute requiredUserType="arquiteto">
            <ArchitectProjects />
          </ProtectedRoute>
        } />
        <Route path="architect/past-projects" element={
          <ProtectedRoute requiredUserType="arquiteto">
            <ArchitectPastProjects />
          </ProtectedRoute>
        } />
        <Route path="architect/applications" element={
          <ProtectedRoute requiredUserType="arquiteto">
            <Applications />
          </ProtectedRoute>
        } />
        <Route path="architect/loyalty" element={
          <ProtectedRoute requiredUserType="arquiteto">
            <LoyaltyProgram />
          </ProtectedRoute>
        } />
        <Route path="architect/project/:id" element={
          <ProtectedRoute requiredUserType="arquiteto">
            <ProjectOverview />
          </ProtectedRoute>
        } />
        <Route path="architect/project/:id/detail" element={
          <ProtectedRoute requiredUserType="arquiteto">
            <ProjectDetail />
          </ProtectedRoute>
        } />

        {/* Admin Routes - No nested Suspense, parent handles it */}
        <Route path="admin/dashboard" element={
          <ProtectedRoute requiredUserType="admin">
            <AdminDashboard />
          </ProtectedRoute>
        } />
        <Route path="admin/applications" element={
          <ProtectedRoute requiredUserType="admin">
            <ArtistApplicationReview />
          </ProtectedRoute>
        } />
        <Route path="admin/profiles" element={
          <ProtectedRoute requiredUserType="admin">
            <ArtistProfileReview />
          </ProtectedRoute>
        } />
        <Route path="admin/blog" element={
          <ProtectedRoute requiredUserType="admin">
            <BlogManagement />
          </ProtectedRoute>
        } />
        <Route path="admin/blog/new" element={
          <ProtectedRoute requiredUserType="admin">
            <BlogEditor />
          </ProtectedRoute>
        } />
        <Route path="admin/blog/edit/:id" element={
          <ProtectedRoute requiredUserType="admin">
            <BlogEditor />
          </ProtectedRoute>
        } />
      </Route>

      {/* Public Blog Routes */}
      <Route path="/blog" element={
        <Suspense fallback={<LoadingFallback />}>
          <BlogListing />
        </Suspense>
      } />
      <Route path="/blog/:slug" element={
        <Suspense fallback={<LoadingFallback />}>
          <BlogPost />
        </Suspense>
      } />

      {/* Legal Pages */}
      <Route path="/terms" element={
        <Suspense fallback={<LoadingFallback />}>
          <TermsAndConditions />
        </Suspense>
      } />
      <Route path="/privacy" element={
        <Suspense fallback={<LoadingFallback />}>
          <PrivacyPolicy />
        </Suspense>
      } />

      {/* Contact Page */}
      <Route path="/contact" element={
        <Suspense fallback={<LoadingFallback />}>
          <Contact />
        </Suspense>
      } />

      {/* 404 Route */}
      <Route path="*" element={<Navigate to="/" replace />} />
    </Routes>
  );
};

export default AppRoutes;
