import React, { createContext, useState, useEffect, useContext, useRef, useCallback } from 'react';
import { supabase } from '../supabaseClient';

const AuthContext = createContext({});

export const useAuth = () => useContext(AuthContext);

export const AuthProvider = ({ children }) => {
  // Try to load cached auth state immediately for optimistic UI
  const getCachedAuthState = () => {
    try {
      const cached = localStorage.getItem('3dmatch_auth_cache');
      if (cached) {
        const parsed = JSON.parse(cached);
        // Only use cache if less than 5 minutes old
        if (Date.now() - parsed.timestamp < 300000) {
          return { user: parsed.user, profile: parsed.profile };
        }
      }
    } catch (e) {
      console.log('Failed to load cached auth state');
    }
    return { user: null, profile: null };
  };

  const cached = getCachedAuthState();
  
  const [user, setUser] = useState(cached.user);
  const [profile, setProfile] = useState(cached.profile);
  const [loading, setLoading] = useState(!cached.user); // Only show loading if no cache
  const [error, setError] = useState(null);
  
  const isMountedRef = useRef(true);
  const profileFetchController = useRef(null);

  // Cache auth state for optimistic loading
  const cacheAuthState = (user, profile) => {
    try {
      localStorage.setItem('3dmatch_auth_cache', JSON.stringify({
        user: user ? { id: user.id, email: user.email } : null,
        profile,
        timestamp: Date.now()
      }));
    } catch (e) {
      console.log('Failed to cache auth state');
    }
  };

  // Clear auth cache
  const clearAuthCache = () => {
    try {
      localStorage.removeItem('3dmatch_auth_cache');
    } catch (e) {
      // Ignore
    }
  };

  useEffect(() => {
    isMountedRef.current = true;

    // Initialize auth - this runs in background and doesn't block UI
    const initAuth = async () => {
      try {
        const { data: { session }, error } = await supabase.auth.getSession();

        if (error) {
          console.error('Session error:', error);
          if (isMountedRef.current) {
            setUser(null);
            setProfile(null);
            setLoading(false);
            clearAuthCache();
          }
          return;
        }

        if (!isMountedRef.current) return;

        if (session?.user) {
          setUser(session.user);
          // Fetch profile in background - doesn't block UI
          fetchProfile(session.user.id);
        } else {
          setUser(null);
          setProfile(null);
          setLoading(false);
          clearAuthCache();
        }
      } catch (err) {
        console.error('Init auth error:', err);
        if (isMountedRef.current) {
          setLoading(false);
        }
      }
    };

    // Set up auth state listener
    const { data: { subscription } } = supabase.auth.onAuthStateChange(
      async (event, session) => {
        console.log('Auth event:', event);
        
        if (!isMountedRef.current) return;

        if (session?.user) {
          setUser(session.user);
          // Profile fetch is non-blocking
          fetchProfile(session.user.id);
        } else {
          setUser(null);
          setProfile(null);
          setLoading(false);
          clearAuthCache();
        }
      }
    );

    // Start initialization
    initAuth();

    // Cleanup
    return () => {
      isMountedRef.current = false;
      subscription.unsubscribe();
      
      // Cancel any in-flight profile fetch
      if (profileFetchController.current) {
        profileFetchController.current.abort();
      }
    };
  }, []);

  // Non-blocking profile fetch
  const fetchProfile = useCallback(async (userId) => {
    // Cancel previous fetch if still running
    if (profileFetchController.current) {
      profileFetchController.current.abort();
    }

    // Create new abort controller for this fetch
    profileFetchController.current = new AbortController();
    const signal = profileFetchController.current.signal;

    try {
      const { data, error } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', userId)
        .abortSignal(signal)
        .single();

      // Check if request was aborted
      if (signal.aborted) return;
      
      if (!isMountedRef.current) return;

      if (error) {
        // Profile doesn't exist - create it
        if (error.code === 'PGRST116') {
          await createProfileFromAuth(userId);
        } else {
          console.error('Profile fetch error:', error);
          setError('Failed to load profile');
        }
      } else {
        setProfile(data);
        setError(null);
        cacheAuthState(user, data);
      }
    } catch (err) {
      if (err.name === 'AbortError') return;
      console.error('Unexpected profile fetch error:', err);
      if (isMountedRef.current) {
        setError('Failed to load profile');
      }
    } finally {
      if (isMountedRef.current) {
        setLoading(false);
      }
    }
  }, []);

  // Create profile from auth metadata
  const createProfileFromAuth = async (userId) => {
    try {
      const { data: { user: authUser } } = await supabase.auth.getUser();
      const userType = authUser?.user_metadata?.user_type || 'artista';
      const fullName = authUser?.user_metadata?.full_name || 'User';

      const { data: newProfile, error } = await supabase
        .from('profiles')
        .insert([{
          id: userId,
          user_type: userType,
          full_name: fullName,
          approval_status: 'pending'
        }])
        .select()
        .single();

      if (!error && newProfile && isMountedRef.current) {
        setProfile(newProfile);
        setError(null);
        cacheAuthState(user, newProfile);
      }
    } catch (err) {
      console.error('Failed to create profile:', err);
    }
  };

  const signUp = async (email, password, userType, fullName) => {
    try {
      setLoading(true);
      setError(null);

      const { data, error } = await supabase.auth.signUp({
        email,
        password,
        options: {
          data: {
            user_type: userType,
            full_name: fullName,
          }
        }
      });

      if (error) throw error;

      // Profile will be auto-created by database trigger
      if (data.user) {
        // Give database trigger time to create profile
        await new Promise(resolve => setTimeout(resolve, 1000));
        
        // Update profile to ensure data is correct
        await supabase
          .from('profiles')
          .update({ user_type: userType, full_name: fullName })
          .eq('id', data.user.id);
      }

      return { data, error: null };
    } catch (error) {
      setError(error.message);
      return { data: null, error };
    } finally {
      setLoading(false);
    }
  };

  const signIn = async (email, password) => {
    try {
      setLoading(true);
      setError(null);

      const { data, error } = await supabase.auth.signInWithPassword({
        email,
        password,
      });

      if (error) throw error;
      if (!data?.user) throw new Error('Login failed - no user data');

      // Profile will be fetched by onAuthStateChange
      return { data, error: null };
    } catch (error) {
      console.error('Sign in error:', error);
      setError(error.message);
      setLoading(false);
      return { data: null, error };
    }
  };

  const signOut = async () => {
    try {
      const { error } = await supabase.auth.signOut();
      if (error) throw error;

      setUser(null);
      setProfile(null);
      setError(null);
      clearAuthCache();

      // Clear other app data but preserve settings
      const darkMode = localStorage.getItem('darkMode');
      localStorage.clear();
      if (darkMode !== null) {
        localStorage.setItem('darkMode', darkMode);
      }
    } catch (error) {
      console.error('Sign out error:', error);
      // Clear local state anyway
      setUser(null);
      setProfile(null);
      clearAuthCache();
    }
  };

  const updateProfile = async (updates) => {
    try {
      setError(null);
      
      const { data, error } = await supabase
        .from('profiles')
        .update({ ...updates, updated_at: new Date().toISOString() })
        .eq('id', user.id)
        .select()
        .single();

      if (error) throw error;
      
      setProfile(data);
      cacheAuthState(user, data);
      
      return { data, error: null };
    } catch (error) {
      setError(error.message);
      return { data: null, error };
    }
  };

  const refreshProfile = async () => {
    if (user?.id) {
      await fetchProfile(user.id);
    }
  };

  const value = {
    user,
    profile,
    loading,
    error,
    signUp,
    signIn,
    signOut,
    updateProfile,
    refreshProfile
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};